static inline int hex2chr(const char *s) /* <=== hex2chr */ 
{
	unsigned int val = hexval(s[0]);
	return (val & ~0xf) ? val : (val << 4) | hexval(s[1]);
}

static int check_url_component(const char *url, int quiet, /* <=== check_url_component */ 
			       const char *name, const char *value)
{
	if (!value)
		return 0;
	if (!strchr(value, '\n'))
		return 0;

	if (!quiet)
		warning(_("url contains a newline in its %s component: %s"),
			name, url);
	return -1;
}

char *strbuf_detach(struct strbuf *sb, size_t *sz) /* <=== strbuf_detach */ 
{
	char *res;
	strbuf_grow(sb, 0);
	res = sb->buf;
	if (sz)
		*sz = sb->len;
	strbuf_init(sb, 0);
	return res;
}

